private static DateFormat createDateFormat(String format, TimeZone timezone) {
    SimpleDateFormat sdf = new SimpleDateFormat(format, new DateFormatSymbols(Locale.US));
    if (timezone != null) {
        sdf.setTimeZone(timezone);
    }
    return sdf;
}
